import type { StudentGroupingAttribute } from './student.js';

export type RuleMode = 'off' | 'preferred' | 'strict';

export type RulePriority = 'low' | 'medium' | 'high' | 'critical';

export interface AdjacencyRule {
  enabled: boolean;
  attribute: StudentGroupingAttribute;
  horizontal: boolean;
  vertical: boolean;
  diagonal: boolean;
  mode: RuleMode; // 'strict' = hard constraint, 'preferred' = soft, 'off' = disabled
  priority: RulePriority;
}

export interface DistributionEntry {
  roomId: string;
  branch: string;
  count?: number; // undefined => AUTO
  mode: RoomDistributionMode;
}

export type RoomDistributionMode = 'strict' | 'preferred' | 'auto';

export interface ContinuityRule {
  mode: RuleMode;
  priority: RulePriority;
}

export type UtilizationStrategy = 'compact' | 'spread' | 'balanced' | 'custom';

export type YearMixingMode = 'mixed' | 'year-wise' | 'custom';
export type BranchMixingMode = 'mixed' | 'partial' | 'branch-specific' | 'custom';

export type AllocationMode = 'auto' | 'strict-custom' | 'balanced' | 'minimum-rooms' | 'maximum-separation';

export interface RuleConfig {
  adjacencyRules: AdjacencyRule[];
  distribution: DistributionEntry[];
  rollContinuity: ContinuityRule;
  branchContinuity: ContinuityRule;
  utilizationStrategy: UtilizationStrategy;
  yearMixing: YearMixingMode;
  branchMixing: BranchMixingMode;
  allocationMode: AllocationMode;
  priorityWeights: Record<string, number>;
}

export function defaultRuleConfig(): RuleConfig {
  return {
    adjacencyRules: [
      {
        enabled: true,
        attribute: 'branch',
        horizontal: true,
        vertical: true,
        diagonal: false,
        mode: 'strict',
        priority: 'high',
      },
    ],
    distribution: [],
    rollContinuity: { mode: 'preferred', priority: 'medium' },
    branchContinuity: { mode: 'off', priority: 'low' },
    utilizationStrategy: 'balanced',
    yearMixing: 'mixed',
    branchMixing: 'mixed',
    allocationMode: 'auto',
    priorityWeights: {
      safety: 100,
      oneSeatPerStudent: 100,
      adjacency: 80,
      explicitDistribution: 70,
      rollContinuity: 50,
      branchBalancing: 40,
      other: 20,
    },
  };
}

/**
 * Detect statically-contradictory strict rule combinations before the solver
 * ever runs (spec: "strict branch continuity conflicts with strict same-branch
 * adjacency"). Returns human-readable contradiction descriptions.
 */
export function detectRuleContradictions(config: RuleConfig): string[] {
  const problems: string[] = [];

  if (config.branchContinuity.mode === 'strict') {
    const strictBranchAdjacency = config.adjacencyRules.find(
      (r) => r.enabled && r.attribute === 'branch' && r.mode === 'strict' && (r.horizontal || r.vertical || r.diagonal)
    );
    if (strictBranchAdjacency) {
      problems.push(
        'Strict branch continuity requires same-branch students to sit together, but a strict same-branch adjacency restriction forbids them from being adjacent. These cannot both hold in a contiguous block larger than 1 seat.'
      );
    }
  }

  const strictDistributionCount = config.distribution.filter((d) => d.mode === 'strict' && d.count !== undefined);
  const roomTotals = new Map<string, number>();
  for (const d of strictDistributionCount) {
    roomTotals.set(d.roomId, (roomTotals.get(d.roomId) ?? 0) + (d.count ?? 0));
  }
  // Room-capacity cross-check happens in the feasibility checker (needs room data);
  // this function only flags rule-vs-rule contradictions that need no data.

  return problems;
}
